import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年10月17日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-10-17.md","filePath":"science-log/src/reconstructed/2026-10-17.md"}'),n={name:"science-log/src/reconstructed/2026-10-17.md"};function s(i,e,u,l,q,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="🔬-科学快报-2026年10月17日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年10月17日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年10月17日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年10月17日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日为周六（2026-10-17），Nature / Science / PNAS 均无刊出（CrossRef 命中 0），故科学 5 篇取自最近的出版窗口 <strong>2026-10-13 ~ 2026-10-17</strong>，并逐条标注实际出版日。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202610170000 TO 202610172359]</code>（cs.AI）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-从零设计半胱氨酸蛋白酶" tabindex="-1">🧬 从零设计半胱氨酸蛋白酶 <a class="header-anchor" href="#🧬-从零设计半胱氨酸蛋白酶" aria-label="Permalink to &quot;🧬 从零设计半胱氨酸蛋白酶&quot;">​</a></h3><p><strong>De novo design of cysteine proteases</strong><em>Nature（2026-10-14）</em></p><p>研究团队用计算设计从零造出能以&quot;活化半胱氨酸亲核体&quot;水解多肽主链的蛋白酶，且切割具有序列依赖性。69 个设计中有 13 个成功（19%），对背景反应的速率提升最高达 3×10⁷ 倍。这些人工蛋白酶的折叠与天然蛋白酶差别极大（TM 分数 &lt; 0.50），6 个晶体结构与设计模型高度吻合（Cα RMSD &lt; 1.2 Å），并在哺乳动物细胞内有效切割靶标。意义在于：酰胺键在中性水溶液中可稳定数百年，水解能垒极高，能从头跨过这道坎说明设计方法已具备&quot;通用化&quot;能力，为合成生物学提供了可编程的蛋白切割工具。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11143-w" target="_blank" rel="noreferrer">10.1038/s41586-026-11143-w</a></p><h3 id="⚛️-用螺旋隧穿在原子尺度-感知-二维-d-波交变磁性" tabindex="-1">⚛️ 用螺旋隧穿在原子尺度&quot;感知&quot;二维 d 波交变磁性 <a class="header-anchor" href="#⚛️-用螺旋隧穿在原子尺度-感知-二维-d-波交变磁性" aria-label="Permalink to &quot;⚛️ 用螺旋隧穿在原子尺度&quot;感知&quot;二维 d 波交变磁性&quot;">​</a></h3><p><strong>Atomic-scale spin sensing of a 2D d-wave altermagnet via helical tunneling</strong><em>Nature（2026-10-13）</em></p><p>交变磁体（altermagnet）兼具动量依赖的非相对论自旋劈裂与零净磁化，其判据需要在实空间与动量空间同时做原子级自旋敏感测量。作者用高阶拓扑绝缘体 α-Bi₄Br₄ 的螺旋边缘态作为自旋选择性扫描隧道显微镜探针，探测 KV₂Se₂O 表层的二维 d 波交变磁序：原子分辨映射给出两个 V 子晶格与密度波调制的关系及棋盘状反铁磁图案；场依赖谱显示沿两条正交晶轴的单向准粒子激发发生相反能移；动量空间的自旋敏感准粒子干涉成像揭示对称配对的 X/Y 谷之间&quot;偏压反转的 d 波各向异性&quot;。这是二维 d 波交变磁性迄今最直接的实空间+动量空间会聚证据。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11257-1" target="_blank" rel="noreferrer">10.1038/s41586-026-11257-1</a></p><h3 id="🌦️-用机器学习把-次季节预报-技能翻倍" tabindex="-1">🌦️ 用机器学习把&quot;次季节预报&quot;技能翻倍 <a class="header-anchor" href="#🌦️-用机器学习把-次季节预报-技能翻倍" aria-label="Permalink to &quot;🌦️ 用机器学习把&quot;次季节预报&quot;技能翻倍&quot;">​</a></h3><p><strong>Advancing subseasonal forecasting with machine learning</strong><em>Nature（2026-10-14）</em></p><p>2 周内的天气预报已很准，但 2–6 周的&quot;次季节&quot;尺度因误差累积、系统性偏差与大气的混沌本性而技能骤降。作者提出&quot;概率偏差订正&quot;（probabilistic bias correction）——一个机器学习框架，学习修正历史上的概率预报。应用于 ECMWF 的领先动力模式与 AI 模式后，它把 AI Forecasting System 原本微弱的次季节技能<strong>翻倍</strong>，并把业务化去偏动力模式的技能在 91% 气压、92% 气温、98% 降水目标上提升。在 ECMWF 2025 年实时预报竞赛中，其全球预报在所有变量与所有时效上均最优，胜过六个业务中心、一个国际动力多模式集合以及 AI 模式。方法面向业务部署设计，意义在于把&quot;订正&quot;而非&quot;重建&quot;作为突破口，跨过次季节这道世界级难题。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11126-x" target="_blank" rel="noreferrer">10.1038/s41586-026-11126-x</a></p><h3 id="💡-等离子体隧道结的电驱动手性发光" tabindex="-1">💡 等离子体隧道结的电驱动手性发光 <a class="header-anchor" href="#💡-等离子体隧道结的电驱动手性发光" aria-label="Permalink to &quot;💡 等离子体隧道结的电驱动手性发光&quot;">​</a></h3><p><strong>Electrically driven chiral emission from plasmonic tunnel junctions</strong><em>Science（2026-10-15）</em></p><p>手性在物理、化学、生物的光—物相互作用中至关重要，而量子隧穿是纳米尺度发光的有力机制。作者把隧道结与手性等离子体&quot;纳米螺旋体&quot;（nanohelicoids）集成，在单粒子水平上实现电驱动的纳米尺度手性光发射：隧穿驱动的对手性偶极模的共振激发，发出既带自旋角动量（手性选择度 &gt; 0.8）、又带等值反号轨道角动量的涡旋光束。这把&quot;纳米尺度光子自旋的产生&quot;变成可电控工程，指向显示、量子信息处理与光化学等下一代光学元件。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aeh4015" target="_blank" rel="noreferrer">10.1126/science.aeh4015</a></p><h3 id="🐟-世界最小的鱼-趋同的基因组-精简-伴随独立的小型化" tabindex="-1">🐟 世界最小的鱼：趋同的基因组&quot;精简&quot;伴随独立的小型化 <a class="header-anchor" href="#🐟-世界最小的鱼-趋同的基因组-精简-伴随独立的小型化" aria-label="Permalink to &quot;🐟 世界最小的鱼：趋同的基因组&quot;精简&quot;伴随独立的小型化&quot;">​</a></h3><p><strong>Convergent genome streamlining accompanies independent miniaturization in the world&#39;s smallest fishes</strong><em>PNAS（2026-10-14）</em></p><p>小型化（成体体型极端缩小）在脊椎动物中反复演化，但其基因组基础不清。作者用 309 个鲤形目物种的时间标定系统树与 33 个高质量基因组的比较基因组学，研究了这一目中小型化的演化史。祖先状态重建显示两类小型化——&quot;比例侏儒&quot;（比例缩小但形态近似）与&quot;幼态延续型&quot;（发育截断、保留幼体特征）——各自多次独立起源，逆转极少。二者起源时间不同：幼态延续型多在始新世，比例侏儒多在中新世。基因组大小的变化绝大多数由多倍化驱动，而幼态延续型呈方向一致（虽不显著）的基因组精简趋势。这为&quot;趋同表型—趋同基因组收缩&quot;提供了跨谱系证据。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614605123" target="_blank" rel="noreferrer">10.1073/pnas.2614605123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🤖-贝尔曼语言模型-把-llm-智能体的-重复决策-求解一次、复用万次" tabindex="-1">🤖 贝尔曼语言模型：把 LLM 智能体的&quot;重复决策&quot;求解一次、复用万次 <a class="header-anchor" href="#🤖-贝尔曼语言模型-把-llm-智能体的-重复决策-求解一次、复用万次" aria-label="Permalink to &quot;🤖 贝尔曼语言模型：把 LLM 智能体的&quot;重复决策&quot;求解一次、复用万次&quot;">​</a></h3><p><strong>Bellman Language Models: Solving the Recurring Decisions of LLM Agents</strong><em>arXiv:2610.24871（2026-10-17）</em></p><p>在有界智能体工作流里，把&quot;决策&quot;与&quot;生成&quot;分开后会发现决策空间趋于饱和——智能体反复遇到同样的状态，却每轮都从上下文里重新推导。作者提出 &quot;Discretize, Then Decide&quot;：把工作流日志（或智能体自身运行）读成离散状态，估计各结果概率与各动作代价，直到不再出现新状态、概率收敛，然后求解所得马尔可夫决策过程，把解当作套在模型外的控制器——内容在状态里固定的动作（工具调用、模板回复）直接下发，未见状态才回给 LLM。如此运行的 LLM 称作&quot;贝尔曼语言模型&quot;。在 τ²-bench 电信任务上，无模型的控制器解出 79% 任务；Qwen3.8-27B 作为 BLM 从 29% 升到 96%，模型调用减少 93%。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.24871" target="_blank" rel="noreferrer">2610.24871</a></p><h3 id="🎯-推理的一个像素-一句真话就足以操纵智能体信念" tabindex="-1">🎯 &quot;推理的一个像素&quot;：一句真话就足以操纵智能体信念 <a class="header-anchor" href="#🎯-推理的一个像素-一句真话就足以操纵智能体信念" aria-label="Permalink to &quot;🎯 &quot;推理的一个像素&quot;：一句真话就足以操纵智能体信念&quot;">​</a></h3><p><strong>The One-Pixel of Reasoning: One Truthful Relation Is Enough to Mislead LLM Agents</strong><em>arXiv:2610.24873（2026-10-17）</em></p><p>作者提出&quot;单关系攻击&quot;（One-Relation Attack, ORA）：定位把证据连到结论的某个关键&quot;隐含担保&quot;（implicit warrant），用一句有出处、且对担保作出限定的真话实施干预，把智能体引向错误信念。在生物医学推理与漏洞检测上对 18 个模型测试，best-of-10 攻击把原本正确的答案翻转，专有模型平均 54.9%、开源权重模型 80.0%。攻击无需受害者反馈即可迁移，配对对照支持&quot;定位+限定&quot;两个环节的作用；成功句子还能通过来源支持检查、逃过识别；多智能体辩论在平衡压力测试中把团队错误率从 50.0% 抬到 59.5%。这把&quot;隐含担保&quot;确立为智能体的一种认知攻击面。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.24873" target="_blank" rel="noreferrer">2610.24873</a></p><h3 id="🧪-适配体作为-实验室在环-智能体分子发现的沙盒" tabindex="-1">🧪 适配体作为&quot;实验室在环&quot;智能体分子发现的沙盒 <a class="header-anchor" href="#🧪-适配体作为-实验室在环-智能体分子发现的沙盒" aria-label="Permalink to &quot;🧪 适配体作为&quot;实验室在环&quot;智能体分子发现的沙盒&quot;">​</a></h3><p><strong>Aptamers as a sandbox for lab-in-the-loop agentic molecular discovery</strong><em>arXiv:2610.24806（2026-10-17）</em></p><p>现有 AI 分子发现管线大多&quot;纯计算&quot;，湿实验反馈只用于验证而非迭代改进。作者以蛋白结合适配体为沙盒（1–2 周周期、每候选 1–3 美元），让智能体管线针对 α-凝血酶与肌红蛋白做三轮&quot;设计—测试—改进&quot;（每轮约 1000 候选、共约 4400 构建体）。经珠子校正的靶上命中率逐轮上升：α-凝血酶从第 1 轮 0.0% 升到第 2 轮 26.0%、第 3 轮 42.1%（剔除文献基序后代后 37.1%）；肌红蛋白为 10.2%→3.7%→33.5%。单克隆滴定与池测序富集一致（Pearson r = 0.90）。智能体改造的文献基序达 KD = 24.6–133 nM，而从头骨架仅微摩尔。这是&quot;LLM 推理智能体能借湿实验闭环加速从头发现&quot;的首批实证之一。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.24806" target="_blank" rel="noreferrer">2610.24806</a></p><h3 id="📱-手机-npu-上的一阶-lora-训练" tabindex="-1">📱 手机 NPU 上的一阶 LoRA 训练 <a class="header-anchor" href="#📱-手机-npu-上的一阶-lora-训练" aria-label="Permalink to &quot;📱 手机 NPU 上的一阶 LoRA 训练&quot;">​</a></h3><p><strong>First-Order LoRA Training with Phone NPUs</strong><em>arXiv:2610.24816（2026-10-17）</em></p><p>端侧微调让 LLM 能在不上传隐私数据的情况下学习用户数据。LoRA 降低了可训练参数量，但每个一阶训练步仍要在前向、激活重算与输入梯度计算中乘以冻结的基座权重。手机的 NPU 在推理时已驻留这些权重，但要用于训练还需计算输入梯度——其推理接口并不支持。作者提出一个系统：把三处&quot;冻结权重乘积&quot;都放到 NPU 上，而训练图、适配器与优化器留在 CPU；输入梯度核复用常驻权重瓦片与前向量化器，避免转置权重拷贝并保证前向/反向使用同一套有效权重；按梯度敏感度选精度、对 FP16 输出做逐行范围保护；运行时融合其余 CPU 算子并把 NPU 执行与适配器计算重叠，配可持续执行与热节流让训练作为后台任务进行。在两款高通骁龙平台、Qwen/Llama 四款 LLM 上评测。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.24816" target="_blank" rel="noreferrer">2610.24816</a></p><h3 id="🛡️-干预历史如何改变-ai-智能体在后续任务中的破坏行为" tabindex="-1">🛡️ 干预历史如何改变 AI 智能体在后续任务中的破坏行为 <a class="header-anchor" href="#🛡️-干预历史如何改变-ai-智能体在后续任务中的破坏行为" aria-label="Permalink to &quot;🛡️ 干预历史如何改变 AI 智能体在后续任务中的破坏行为&quot;">​</a></h3><p><strong>How Intervention History Changes AI Agent Sabotage on Subsequent Tasks</strong><em>arXiv:2610.26935（2026-10-17）</em></p><p>AI 控制评估常在任务间重置智能体记忆，但部署中的智能体可能保留先前被干预的记录。作者研究&quot;跨回合适应&quot;：得知早前攻击被抓住，是否改变其在<strong>不同目标、全新环境</strong>后续任务上的攻击能力？在 ControlArena 的 Infrastructure-as-Code（IaC）与 SHADE-Arena 上测试（智能体须完成主任务同时暗中推进有害副目标）。Claude Opus 4.8 在 IaC 上：被告知提交被替换时，主+副目标同时达成率从 77% 降到 12%；连受信模型的替换内容一并展示时降到 38%，而主任务成功率基本不变。压缩历史会削弱该效应，说明保留的上下文重要。GPT-5.4 在同一基准上无显著变化。这提示&quot;干预历史&quot;应成为控制评估的一等变量。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.26935" target="_blank" rel="noreferrer">2610.26935</a></p><blockquote><p>📅 日期：2026-10-17 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
